<?php if ( post_password_required() ) { return; } ?><section id="comments" class="comments-area"><h2 class="comments-title"><?php comments_number( esc_html__( 'No reviews yet', 'souqify' ), esc_html__( 'One comment', 'souqify' ), esc_html__( '% comments', 'souqify' ) ); ?></h2><?php if ( have_comments() ) : ?><ol class="comment-list"><?php wp_list_comments( array( 'style' => 'ol', 'short_ping' => true, 'avatar_size' => 48 ) ); ?></ol><?php the_comments_navigation(); endif; if ( comments_open() ) { comment_form(); } ?></section>
